CREATE TYPE "LeadStatus" AS ENUM ('NEW', 'CONTACTED', 'DESIGNED', 'PROPOSAL_SENT', 'WON', 'LOST');
CREATE TABLE "Lead" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "phone" TEXT NOT NULL, "address" TEXT NOT NULL, "status" "LeadStatus" NOT NULL DEFAULT 'NEW', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Lead_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Project" ("id" TEXT NOT NULL, "leadId" TEXT NOT NULL, "roofAreaM2" DOUBLE PRECISION NOT NULL, "annualConsumptionKwh" DOUBLE PRECISION NOT NULL, "roofTiltDeg" DOUBLE PRECISION NOT NULL, "roofAzimuthDeg" DOUBLE PRECISION NOT NULL, "batteryIncluded" BOOLEAN NOT NULL, "electricityPriceEurKwh" DOUBLE PRECISION NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Project_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Simulation" ("id" TEXT NOT NULL, "projectId" TEXT NOT NULL, "systemSizeKwp" DOUBLE PRECISION NOT NULL, "annualYieldKwh" DOUBLE PRECISION NOT NULL, "selfConsumptionPct" DOUBLE PRECISION NOT NULL, "annualSavingsEur" DOUBLE PRECISION NOT NULL, "systemCostEur" DOUBLE PRECISION NOT NULL, "paybackYears" DOUBLE PRECISION NOT NULL, "monthlyYieldKwh" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Simulation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Proposal" ("id" TEXT NOT NULL, "projectId" TEXT NOT NULL, "publicId" TEXT NOT NULL, "summary" TEXT NOT NULL, "totalPriceEur" DOUBLE PRECISION NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Proposal_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Project_leadId_key" ON "Project"("leadId"); CREATE UNIQUE INDEX "Proposal_projectId_key" ON "Proposal"("projectId"); CREATE UNIQUE INDEX "Proposal_publicId_key" ON "Proposal"("publicId"); CREATE INDEX "Lead_status_idx" ON "Lead"("status"); CREATE INDEX "Lead_createdAt_idx" ON "Lead"("createdAt"); CREATE INDEX "Project_leadId_idx" ON "Project"("leadId"); CREATE INDEX "Simulation_projectId_createdAt_idx" ON "Simulation"("projectId", "createdAt");
ALTER TABLE "Project" ADD CONSTRAINT "Project_leadId_fkey" FOREIGN KEY ("leadId") REFERENCES "Lead"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Simulation" ADD CONSTRAINT "Simulation_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Proposal" ADD CONSTRAINT "Proposal_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE;